SELECT percentile_cont(0.9) within GROUP (ORDER BY male_icu_patients_with_instability_sorted.instability_hours) AS ninety_percentile, male_icu_patients_with_instability_sorted.los AS avg_los, male_icu_patients_with_instability_sorted.dod AS avg_mortality_rate, AVG(male_icu_patients_with_instability_sorted.instability_hours) AS avg_hours_with_instability FROM male_icu_patients_with_instability_sorted GROUP BY male_icu_patients_with_instability_sorted.subject_id, male_icu_patients_with_instability_sorted.hadm_id, male_icu_patients_with_instability_sorted.los, male_icu_patients_with_instability_sorted.dod ORDER BY male_icu_patients_with_instability_sorted.subject_id, male_icu_patients_with_instability_sorted.hadm_id, male_icu_patients_with_instability_sorted.los, male_icu_patients_with_instability_sorted.dod NULLS LAST;